interface BrowserTab {
  id: string;
  url: string;
  title: string;
  favicon?: string;
  isLoading: boolean;
  error?: string;
  lastVisited: number;
  bookmarked: boolean;
}

interface Bookmark {
  id: string;
  url: string;
  title: string;
  category: 'service' | 'tool' | 'doc' | 'frequent';
  icon?: React.ReactNode;
}

interface HistoryEntry {
  url: string;
  title: string;
  timestamp: number;
  tabId: string;
}

interface ConsoleMessage {
  type: 'log' | 'error' | 'warn' | 'info';
  content: string;
  timestamp: number;
  source?: string;
}

interface AIBrowserAction {
  type: 'summarize' | 'explain' | 'extract_links' | 'find_issues' | 'interact';
  payload?: any;
}

