import React, { useEffect, useState } from 'react';
import { adminTokenStore } from '../services/adminTokenStore';
import { getApiBaseUrl } from '../utils/api';
import { THEME_ORDER } from './ThemeConstants';
import { ThemeContext } from './ThemeContext';
import type { Theme } from './ThemeConstants';
import { apiClient } from '../services/apiClient';
import { eventBus, Events } from '../lib/eventBus';

// αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: ThemeContext αªÅαªòαºç αªàαª¬αª░ αª½αª╛αªçαª▓ αªÑαºçαªòαºç αªçαª«αºìαª¬αºïαª░αºìαªƒ αªòαª░αª╛ αª╣αª»αª╝αºçαª¢αºç, αª»αª╛αªñαºç react-refresh αª╕αªñαª░αºìαªòαªñαª╛ αªªαºéαª░ αª╣αª»αª╝
// useTheme hook αªÅαªòαºç αªàαª¬αª░ αª½αª╛αªçαª▓αºç αª╕αª░αª╛αª¿αºï αª╣αª»αª╝αºçαª¢αºç (useTheme.ts)
export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme, setTheme] = useState<Theme>('dark'); // αªíαª┐αª½αª▓αºìαªƒ Deep Space (dark)

  useEffect(() => {
    // αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: Race Condition αªÅαªíαª╝αª╛αªñαºç AbortController αª¼αºìαª»αª¼αª╣αª╛αª░ αªòαª░αª╛ αª╣αª»αª╝αºçαª¢αºç
    const controller = new AbortController();
    const token = adminTokenStore.getDecodedToken();

    if (!token) return;

    // αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: set-state-in-effect αª½αª┐αªòαºìαª╕ ΓÇö αªÑαª┐αª« αª▓αºïαªíαª┐αªé async αª½αª╛αªéαª╢αª¿αºçαª░ αª¡αºçαªñαª░αºç αªòαª░αª╛ αª╣αª»αª╝αºçαª¢αºç
    const loadTheme = async () => {
      // 1. αª▓αºïαªòαª╛αª▓ αª╕αºìαªƒαºïαª░αºçαª£ αªÑαºçαªòαºç αªÑαª┐αª« αª¬αªíαª╝αª╛ (Optimistic Load)
      const localTheme = localStorage.getItem('supremeai_theme') as Theme | null;
      if (localTheme && THEME_ORDER.includes(localTheme)) {
        setTheme(localTheme);
      }

      // 2. αª¼αºìαª»αª╛αªòαªÅαª¿αºìαªí αªÑαºçαªòαºç αª½αºçαªÜ αªòαª░αª╛ (Cross-device sync)
      try {
        const response = await apiClient.get<any>('/api/v1/preferences', { signal: controller.signal });
        if (response.data?.theme) {
          setTheme(response.data.theme);
          localStorage.setItem('supremeai_theme', response.data.theme);
        }
      } catch (err: any) {
        if (err.name !== 'AbortError' && err.name !== 'CanceledError') {
          console.error('Theme sync failed:', err);
        }
      }
    };

    loadTheme();

    // Listen for external theme changes (from other tabs/components)
    const unsub = eventBus.subscribe(Events.THEME_CHANGED, (data) => {
      if (data.theme && THEME_ORDER.includes(data.theme as Theme)) setTheme(data.theme as Theme);
    });

    return () => {
      controller.abort();
      unsub();
    }; // αªòαª«αºìαª¬αºïαª¿αºçαª¿αºìαªƒ αªåαª¿αª«αª╛αªëαª¿αºìαªƒ αª╣αª▓αºç αª░αª┐αªòαºïαª»αª╝αºçαª╕αºìαªƒ αª¼αª╛αªñαª┐αª▓
  }, []);

  useEffect(() => {
    // αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: HTML root αªÅαª▓αª┐αª«αºçαª¿αºìαªƒαºç αªÑαª┐αª« αªòαºìαª▓αª╛αª╕ αªàαºìαª»αª╛αªí αªòαª░αª╛ αª╣αªÜαºìαª¢αºç
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark', 'sunset', 'matrix');
    root.classList.add(theme);
    root.setAttribute('data-theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    // αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: αª¬αª░αª¼αª░αºìαªñαºÇ αªÑαª┐αª«αºç αª╕αª╛αªçαªòαºçαª▓ αªòαª░αª╛ αª╣αªÜαºìαª¢αºç (dark ΓåÆ light ΓåÆ sunset ΓåÆ matrix ΓåÆ dark)
    const currentIndex = THEME_ORDER.indexOf(theme);
    const nextIndex = (currentIndex + 1) % THEME_ORDER.length;
    const newTheme = THEME_ORDER[nextIndex];

    // Optimistic UI Update
    setTheme(newTheme);
    localStorage.setItem('supremeai_theme', newTheme);

    // αª¼αºìαª»αª╛αªòαªÅαª¿αºìαªíαºç async αª╕αª┐αªÖαºìαªò αªòαª░αª╛
    apiClient.post('/api/v1/preferences', { theme: newTheme })
      .catch(err => console.error('Failed to sync theme to DB:', err));

    eventBus.emit(Events.THEME_CHANGED, {
      theme: newTheme,
      isDark: newTheme === 'dark' || newTheme === 'matrix',
      timestamp: Date.now(),
      source: 'theme_provider',
    });
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

/**
 * Γ£à REACT HOOK FOR EVENT BUS
 * Provides easy subscription management with automatic cleanup
 */

import { useEffect, useRef, useCallback } from 'react';
import { eventBus, Events, type EventCallback } from '../lib/eventBus';

interface UseEventBusReturn {
  emit: typeof eventBus.emit;
  subscribe: typeof eventBus.subscribe;
  getListenerCount: typeof eventBus.getListenerCount;
}

/**
 * Hook for subscribing to events with automatic cleanup
 * @param event Event name from Events enum
 * @param callback Handler function
 * @param deps Optional dependency array for re-subscription
 */
export function useEventBus<T = any>(
  event: keyof typeof Events | string,
  callback: EventCallback<T>,
  deps: React.DependencyList = []
): UseEventBusReturn {
  const callbackRef = useRef(callback);
  
  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    const unsubscribe = eventBus.subscribe<T>(event, (data) => {
      callbackRef.current(data);
    });

    return unsubscribe;
  }, [event, ...deps]);

  return {
    emit: useCallback((...args: Parameters<typeof eventBus.emit>) => eventBus.emit(...args), []),
    subscribe: useCallback((...args: Parameters<typeof eventBus.subscribe>) => eventBus.subscribe(...args), []),
    getListenerCount: useCallback((...args: Parameters<typeof eventBus.getListenerCount>) => eventBus.getListenerCount(...args), []),
  };
}

/**
 * Hook for emitting events (convenience wrapper)
 */
export function useEventEmitter() {
  const emit = useCallback(<T = any>(event: keyof typeof Events | string, data?: T) => {
    eventBus.emit(event, data);
  }, []);

  return { emit };
}

/**
 * Hook for multiple event subscriptions
 */
export function useEventBusMulti(
  subscriptions: Array<{
    event: keyof typeof Events | string;
    handler: EventCallback;
  }>
): void {
  useEffect(() => {
    const unsubscribers = subscriptions.map(({ event, handler }) =>
      eventBus.subscribe(event, handler)
    );

    return () => unsubscribers.forEach(unsub => unsub());
  }, [subscriptions]);
}

export default useEventBus;

/**
 * SuperAI Cache Manager - FREE-TIER OPTIMIZED
 * 
 * Features:
 * - Multi-tier TTL strategy (save Redis commands!)
 * - Smart compression (reduce memory usage)
 * - Batch operations (reduce round-trips)
 * - Pattern-based invalidation
 * - Usage tracking (stay within free limits!)
 * 
 * Free Tier Limits:
 * - Upstash: 10,000 commands/day
 * - Storage: 256 MB max
 * - This manager helps you MAXIMIZE usage!
 */

import { Redis } from '@upstash/redis';
import { cache } from 'react';

// Γ£à ENHANCED: Proper compression using Compression Streams API
async function compress(data: string): Promise<string> {
  if (data.length < 1024) return data;  // Don't bother compressing small payloads

  try {
    if (typeof CompressionStream !== 'undefined') {
      const encoder = new TextEncoder();
      const compressed = new Blob([encoder.encode(data)]).stream()
        .pipeThrough(new CompressionStream('gzip'));
      const reader = compressed.getReader();
      const chunks: Uint8Array[] = [];
      let totalLength = 0;

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        totalLength += value.length;
      }

      // Only use compressed version if it's actually smaller
      if (totalLength < data.length) {
        const result = new Uint8Array(totalLength);
        let offset = 0;
        for (const chunk of chunks) {
          result.set(chunk, offset);
          offset += chunk.length;
        }
        return btoa(String.fromCharCode(...result));
      }
    }
  } catch (e) {
    console.warn('Compression failed, using raw data:', e);
  }

  return data;
}

// Γ£à ENHANCED: Decompression
async function decompress(data: string): Promise<string> {
  try {
    if (typeof DecompressionStream !== 'undefined' && data.length > 256) {
      const binary = atob(data);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
      }

      const decompressed = new Blob([bytes]).stream()
        .pipeThrough(new DecompressionStream('gzip'));
      const reader = decompressed.getReader();
      const chunks: Uint8Array[] = [];

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
      }

      const decoder = new TextDecoder();
      return decoder.decode(await new Blob(chunks).text());
    }
  } catch (e) {
    console.warn('Decompression failed, returning raw:', e);
  }

  return data;
}

