      return JSON.parse(saved);
    }
  } catch (e) {
    console.error("[SupremeAI Forge] Failed to parse autosave data, clearing cache.", e);
    localStorage.removeItem('supremeai_forge_autosave');
  }
  return null;
};

const EvolutionForgeCanvas = () => {
  const reactFlowWrapper = useRef<HTMLDivElement>(null);

  const autosaved = loadAutosavedFlow();
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>(autosaved?.nodes || initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>(autosaved?.edges || []);

  const [isSaving, setIsSaving] = useState(false);
  const [isExecuting, setIsExecuting] = useState(false);
  const [isDebateOpen, setIsDebateOpen] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [debateLogs, setDebateLogs] = useState<any[]>([]);
  const { toObject } = useReactFlow();
  const { showToast } = useToast();

  const [showDeployDialog, setShowDeployDialog] = useState(false);
  const [deployStatus, setDeployStatus] = useState('idle');
  const [deployError, setDeployError] = useState<string | null>(null);

  useEffect(() => {
    const token = localStorage.getItem('supremeai_auth_token');
    const sse = new EventSource(`${getApiBaseUrl()}/api/v1/swarm/stream${token ? `?token=${encodeURIComponent(token)}` : ''}`);

    sse.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data);
        if (payload.type === 'DEBATE_UPDATE') {
          setIsDebateOpen(true);
          const logData = payload.data;

          let message = '';
          if (logData.state === 'PROPOSING') message = `Starting Debate Cycle ${logData.iteration || ''}`;
          if (logData.proposals_count) message = `Generated ${logData.proposals_count} proposals. Judge evaluating...`;
          if (logData.feedback) message = `Rethinking based on feedback: ${logData.feedback}`;
          if (logData.winning_agent) message = `Consensus reached by ${logData.winning_agent}`;

          setDebateLogs(prev => [...prev, {
            agentName: 'ConsensusEngine',
            status: logData.state,
            message: message || `Status updated to ${logData.state}`
          }]);
        }
      } catch (err) {
        console.error("SSE Parse error", err);
      }
    };

    return () => sse.close();
  }, []);

  // Listen for newly installed skills
  useEffect(() => {
    const handleSkillCreated = (payload: any) => {
      showToast(`New skill integrated: ${payload.skillId}`, 'success');
    };
    eventBus.on(Events.SKILL_AUTO_CREATED, handleSkillCreated);
    return () => {
      eventBus.off(Events.SKILL_AUTO_CREATED, handleSkillCreated);
    };
  }, [showToast]);

  // ≡ƒöä Attach auto-save listener
  useForgeAutosave(nodes, edges);

  const onConnect = useCallback(
    (params: Connection | Edge) => setEdges((eds) => addEdge({ ...params, animated: true }, eds)),
    [setEdges]
  );

  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();

      const type = event.dataTransfer.getData('application/reactflow');
      if (typeof type === 'undefined' || !type) return;

      // Extract the JSON payload we sent from the sidebar
      const nodeDataString = event.dataTransfer.getData('application/json');
      const nodeData = nodeDataString ? JSON.parse(nodeDataString) : {};

      const position = {
        x: event.clientX - (reactFlowWrapper.current?.getBoundingClientRect().left ?? 0),
        y: event.clientY - (reactFlowWrapper.current?.getBoundingClientRect().top ?? 0),
      };

      const newNode = {
        id: `agent_${Date.now()}`,
        type,
        position,
        data: {
          label: nodeData.label || 'New Node',
          role: nodeData.role || 'Unknown',
          model: nodeData.model || 'Unknown',
          prompt: ''
        },
      };

      setNodes((nds) => nds.concat(newNode));
    },
    [setNodes]
  );

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const buildForgePayload = (name: string, flow: any) => ({
    name,
    description: "Visual Swarm Architecture",
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    nodes: flow.nodes.map((n: any) => ({
      id: n.id,
      type: n.type,
      position: n.position,
      data: n.data
    })),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    edges: flow.edges.map((e: any) => ({
      id: e.id,
      source: e.source,
      target: e.target,
      animated: e.animated || false
    }))
  });

  const handleSaveSwarm = async () => {
    const token = localStorage.getItem('supremeai_auth_token');
    if (!token) {
      showToast('Authentication required to save swarm.', 'error');
      return;
    }

    try {
      setIsSaving(true);
      const payload = buildForgePayload(`Swarm_${Date.now()}`, toObject());

      await apiClient.post('/api/v1/swarm/forge', payload);

      showToast('Swarm blueprint saved successfully! ≡ƒÜÇ', 'success');

      if (payload.nodes && payload.nodes.length > 0) {
        eventBus.emit(Events.SKILL_AUTO_CREATED, {
          name: payload.name,
          agents: payload.nodes.filter((n: any) => n.type === 'agentNode').map((n: any) => n.data.role || 'Agent'),
          nodeCount: payload.nodes.length,
          source: 'evolution_forge',
          canDeploy: true,
          timestamp: Date.now(),
        });
        
        setShowDeployDialog(true);
      }
    } catch (error) {
      console.error('Save failed:', error);
      showToast('Error saving swarm blueprint.', 'error');
    } finally {
      setIsSaving(false);
    }
  };

  const handleExecuteSwarm = async () => {
    const token = localStorage.getItem('supremeai_auth_token');
    if (!token) {
      showToast('Authentication required to execute swarm.', 'error');
      return;
    }

    try {
      setIsExecuting(true);
      const payload = buildForgePayload(`Swarm_${Date.now()}`, toObject());

      // We use a dummy flow_id for now, in a real app this would be the saved swarm ID
      const flowId = `flow_${Date.now()}`;

      await apiClient.post(`/api/v1/swarm/forge/${flowId}/execute`, payload);

      showToast('Swarm execution started successfully! ≡ƒÜÇ Check Swarm Health Dashboard for live telemetry.', 'success');
    } catch (error: any) {
      console.error('Execution failed', error);
      showToast(`Failed to execute swarm: ${error?.response?.data?.detail || error.message || 'Unknown error'}`, 'error');
    } finally {
      setIsExecuting(false);
    }
  };

  const handleDeployToMarketplace = async () => {
    setDeployStatus('deploying');
    setDeployError(null);
    
    try {
      const payload = buildForgePayload(`Swarm_${Date.now()}`, toObject());
      const result = await apiClient.post('/api/skills/deploy-blueprint', {
        name: payload.name,
        description: payload.description || `Auto-generated skill from Evolution Forge`,
        agents: payload.nodes.filter((n: any) => n.type === 'agentNode').map((n: any) => n.data.role || 'Agent'),
        nodes: payload.nodes,
        edges: payload.edges,
        category: 'automation',
      });
      
      setDeployStatus('success');
      
      // Notify listeners
      eventBus.emit(Events.SKILL_APPROVAL_NEEDED, {
        skillId: (result as any).data?.skillId || `skill_${Date.now()}`,
        name: payload.name,
        status: 'pending_review',
        timestamp: Date.now(),
      });
      
      eventBus.emit('deployment_status' as Events, {
        type: 'skill_published',
        skillId: (result as any).data?.skillId || `skill_${Date.now()}`,
        status: 'pending',
        timestamp: Date.now(),
      });
      
      setTimeout(() => {
        setShowDeployDialog(false);
        setDeployStatus('idle');
      }, 2500);
      
    } catch (e: any) {
      setDeployStatus('error');
      setDeployError(e.message || 'Deployment failed');
      console.error('[EvolutionForge] Deploy failed:', e);
    }
  };

  return (
    <div className="flex h-[calc(100vh-64px)] w-full bg-background relative" ref={reactFlowWrapper}>
      <ForgeSidebar />
      <DebateOverlay isOpen={isDebateOpen} logs={debateLogs} />

      <div className="flex-grow h-full relative">
        <div className="absolute top-4 right-4 z-10 flex gap-3">
          <button
            onClick={handleExecuteSwarm}
            disabled={isExecuting || isSaving}
            className={`
              px-6 py-2 rounded-lg font-brand font-bold text-sm text-background
              transition-all duration-fast shadow-[0_0_15px_var(--color-neon-purple)]
              ${isExecuting ? 'bg-neon-purple/50 cursor-not-allowed' : 'bg-neon-purple hover:bg-neon-purple/80'}
            `}
          >
            {isExecuting ? 'Executing...' : 'ΓÜí Execute Flow'}
          </button>

          <button
            onClick={handleSaveSwarm}
            disabled={isSaving || isExecuting}
            className={`
              px-6 py-2 rounded-lg font-brand font-bold text-sm text-background
              transition-all duration-fast shadow-[0_0_15px_var(--color-brand-primary)]
              ${isSaving ? 'bg-brand-primary/50 cursor-not-allowed' : 'bg-brand-primary hover:bg-brand-primary/80'}
            `}
          >
            {isSaving ? 'Saving...' : '≡ƒÆ╛ Save Swarm'}
          </button>
        </div>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onDrop={onDrop}
          onDragOver={onDragOver}
          nodeTypes={nodeTypes}
          fitView
          className="bg-bg-void"
        >
          <Background color="var(--color-border-subtle)" gap={16} />
          <Controls className="bg-card-bg border border-border-subtle fill-text-primary" />
          <MiniMap
            nodeColor="var(--color-brand-primary)"
            maskColor="var(--color-bg-surface)"
            className="bg-background border border-border-subtle"
          />
        </ReactFlow>
      </div>

      {/* Deploy to Marketplace Dialog */}
      {showDeployDialog && (
        <div className="absolute inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center">
          <div className="bg-[#161b22] border border-cyan-500/30 rounded-xl shadow-2xl p-6 w-[450px]">
            <h3 className="text-xl font-bold text-white flex items-center gap-2 mb-4">
              <Sparkles className="text-cyan-400" />
              Deploy to Skill Marketplace
            </h3>
            
            <div className="bg-[#0d1117] p-4 rounded-lg mb-6 border border-slate-700">
              <p className="text-sm text-slate-300 mb-2">Ready to deploy <strong>Current Blueprint</strong>:</p>
              <ul className="text-xs text-slate-400 space-y-1 list-disc pl-4">
                <li><strong>{nodes.filter(n => n.type === 'agentNode').length}</strong> agents configured</li>
                <li><strong>{nodes.length}</strong> nodes in workflow</li>
                <li>Type: General Automation</li>
              </ul>
            </div>
            
            {deployStatus === 'success' ? (
              <div className="text-center py-4">
                <CheckCircle size={48} className="text-green-400 mx-auto mb-3" />
                <h4 className="text-lg font-bold text-white">Successfully Submitted!</h4>
                <p className="text-sm text-slate-400">Your skill is now pending review.</p>
              </div>
            ) : deployStatus === 'error' ? (
              <div className="text-center py-4">
                <AlertCircle size={48} className="text-red-400 mx-auto mb-3" />
                <h4 className="text-lg font-bold text-white">Deployment Failed</h4>
                <p className="text-sm text-red-300 mt-2">{deployError}</p>
              </div>
            ) : (
              <div className="flex items-center gap-3 justify-end">
                <button
                  onClick={() => setShowDeployDialog(false)}
                  className="px-4 py-2 text-sm text-slate-300 hover:text-white transition-colors"
                  disabled={deployStatus === 'deploying'}
                >
                  Cancel
                </button>
                <button
                  onClick={handleDeployToMarketplace}
                  className="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg flex items-center gap-2 transition-colors disabled:opacity-50"
                  disabled={deployStatus === 'deploying'}
                >
                  {deployStatus === 'deploying' ? (
                    'Deploying...'
                  ) : (
                    <>
                      <Upload size={16} />
                      Publish to Marketplace
                    </>
                  )}
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default function EvolutionForge() {
  return (
    <ReactFlowProvider>
      <EvolutionForgeCanvas />
    </ReactFlowProvider>
  );
}

/**
 * SuperAI Cost Optimizer Service (Vite-Compatible)
 * 
 * Replaces broken Next.js middleware with Vite-compatible solution.
 * Can be used as:
 * 1. Service worker for SPA
 * 2. Axios interceptor for API calls
 * 3. React Query configuration
 */

import { getCacheStats, resetCacheStats } from '../lib/cache.manager';

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// CONFIGURATION
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

interface CostOptimizerConfig {
  enableResponseCache: boolean;
  enableRateLimiting: boolean;
  enableCompression: boolean;
  enableDeduplication: boolean;
  rateLimitRequests: number;
  rateLimitWindowMs: number;
  maxPayloadSize: number;
  cacheTTL: {
    static: number;
    api: number;
    ai: number;
  };
}

const DEFAULT_CONFIG: CostOptimizerConfig = {
  enableResponseCache: true,
  enableRateLimiting: true,
  enableCompression: true,
  enableDeduplication: true,
  rateLimitRequests: 10,
  rateLimitWindowMs: 60000,
  maxPayloadSize: 1024 * 1024, // 1MB
  cacheTTL: {
    static: 3600,    // 1 hour for static
    api: 300,      // 5 min for API
    ai: 60,        // 1 min for AI (cache less, fresher data)
  },
};

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// RATE LIMITER (In-Memory with localStorage backup)
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

class RateLimiter {
  private requests: Map<string, number[]> = new Map();
  private config: CostOptimizerConfig;

  constructor(config: CostOptimizerConfig) {
    this.config = config;
    this._loadFromStorage();
  }

  checkLimit(identifier: string): { allowed: boolean; remaining: number; resetTime: Date } {
    const now = Date.now();
    const windowStart = now - this.config.rateLimitWindowMs;

    let timestamps = this.requests.get(identifier) || [];

    // Clean old entries outside window
    timestamps = timestamps.filter(t => t > windowStart);

    if (timestamps.length >= this.config.rateLimitRequests) {
      const oldestInWindow = timestamps[0];
      return {
        allowed: false,
        remaining: 0,
        resetTime: new Date(oldestInWindow + this.config.rateLimitWindowMs)
      };
    }

    // Add current request
    timestamps.push(now);
    this.requests.set(identifier, timestamps);
    this._persistToStorage();

    return {
      allowed: true,
      remaining: this.config.rateLimitRequests - timestamps.length - 1,
      resetTime: new Date(now + this.config.rateLimitWindowMs)
    };
  }

  reset(identifier?: string): void {
    if (identifier) {
      this.requests.delete(identifier);
    } else {
      this.requests.clear();
    }
    this._persistToStorage();
  }

  private _loadFromStorage(): void {
    try {
      const stored = localStorage.getItem('superai_rate_limits');
      if (stored) {
        const parsed = JSON.parse(stored);
        this.requests = new Map(Object.entries(parsed));
      }
    } catch (e) {
      // Storage not available
    }
  }

  private _persistToStorage(): void {
    try {
      const obj: Record<string, number[]> = {};
      this.requests.forEach((value, key) => {
        obj[key] = value;
      });
      localStorage.setItem('superai_rate_limits', JSON.stringify(obj));
    } catch (e) {
      // Storage not available or full
    }
  }
}

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// REQUEST DEDUPLICATOR
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

class RequestDeduplicator {
  private recentRequests: Map<string, { timestamp: number; response: any }> = new Map();
  private windowMs: number = 120000; // 2 minutes

  constructor(windowMs?: number) {
    if (windowMs) this.windowMs = windowMs;
  }

  getHash(data: string): string {
    let hash = 0;
    for (let i = 0; i < data.length; i++) {
      const char = data.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash |= 0;
    }
    return hash.toString();
  }

  check<T>(requestHash: string, fetchFn: () => Promise<T>): Promise<T> {
    const cached = this.recentRequests.get(requestHash);

    if (cached && Date.now() - cached.timestamp < this.windowMs) {
      console.log('Γ£¿ Request deduplicated (cached response reused)');
      return cached.response;
    }

    return fetchFn().then(response => {
      // Cache successful responses
      this.recentRequests.set(requestHash, {
        timestamp: Date.now(),
        response
      });

      // Cleanup old entries periodically
      if (this.recentRequests.size > 200) {
        this._cleanup();
      }

      return response;
    });
  }

  private _cleanup(): void {
    const cutoff = Date.now() - this.windowMs * 2;
    for (const [key, value] of this.recentRequests.entries()) {
      if (value.timestamp < cutoff) {
        this.recentRequests.delete(key);
      }
    }
  }
}

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// MAIN COST OPTIMIZER SERVICE
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

export class CostOptimizerService {
  private config: CostOptimizerConfig;
  private rateLimiter: RateLimiter;
  private deduplicator: RequestDeduplicator;

  constructor(config: Partial<CostOptimizerConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.rateLimiter = new RateLimiter(this.config);
    this.deduplicator = new RequestDeduplicator();
  }

  // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
  // PUBLIC METHODS
  // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

  /**
   * Check if an API call should be allowed (rate limit check)
   */
  canMakeRequest(endpoint: string, userId?: string): { 
    allowed: boolean; 
    remaining: number; 
    retryAfter?: number;
  } {
    if (!this.config.enableRateLimiting) {
      return { allowed: true, remaining: Infinity };
    }

    const identifier = userId || endpoint;
    const result = this.rateLimiter.checkLimit(identifier);

    return {
      allowed: result.allowed,
      remaining: result.remaining,
      retryAfter: result.allowed ? undefined : 
        Math.ceil((result.resetTime.getTime() - Date.now()) / 1000)
    };
  }

  /**
   * Deduplicate a request if similar one was made recently
   */
  async deduplicateRequest<T>(
    requestData: string,
    fetchFn: () => Promise<T>
  ): Promise<T> {
    if (!this.config.enableDeduplication) {
      return fetchFn();
    }

    const hash = this.deduplicator.getHash(requestData);
    return this.deduplicator.check(hash, fetchFn);
  }

  /**
   * Validate payload size
   */
  validatePayloadSize(data: string | object): { valid: boolean; size: number; maxSize: number } {
    const size = typeof data === 'string' ? data.length : JSON.stringify(data).length;
    return {
      valid: size <= this.config.maxPayloadSize,
      size,
      maxSize: this.config.maxPayloadSize
    };
  }

  /**
   * Get optimal cache TTL for a given path/type
   */
  getCacheTTLForPath(path: string): number {
    if (path.includes('/api/ai/') || path.includes('/api/generate')) {
      return this.config.cacheTTL.ai;
    }
    if (path.startsWith('/api/')) {
      return this.config.cacheTTL.api;
    }
    return this.config.cacheTTL.static;
  }

  /**
   * Get full optimization report (for admin dashboard)
   */
  getOptimizationReport(): {
    rateLimits: ReturnType<typeof this.rateLimiter>;
    cacheStats: ReturnType<typeof getCacheStats>;
    config: CostOptimizerConfig;
    savings: {
      estimatedRequestsSaved: number;
      estimatedCostSaved: number;
    };
  } {
    const cacheStats = getCacheStats();
    const hitRate = cacheStats.hits / (cacheStats.hits + cacheStats.misses) || 0;

    return {
      rateLimits: this.rateLimiter as any,
      cacheStats,
      config: this.config,
      savings: {
        estimatedRequestsSaved: cacheStats.hits,
        estimatedCostSaved: Math.round(hitRate * 0.02 * cacheStats.hits)  // $0.02 per saved API call
      }
    };
  }

  /**
   * Reset all optimization state (call monthly)
   */
  resetAll(): void {
    this.rateLimiter.reset();
    resetCacheStats();
    console.log('≡ƒöä Cost optimizer state reset');
  }
}

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// SINGLETON EXPORT
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

let _instance: CostOptimizerService | null = null;

export function getCostOptimizer(config?: Partial<CostOptimizerConfig>): CostOptimizerService {
  if (!_instance) {
    _instance = new CostOptimizerService(config);
  }
  return _instance;
}

// Default export
export default CostOptimizerService;

