/**
 * HealthStream - WebSocket Client for Real-time Service Health Updates
 * 
 * Connects to /api/admin-api/health-stream endpoint
 * Provides reactive hooks for components to consume live health data.
 */

import { useEffect, useRef, useState, useCallback } from 'react';

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// TYPES
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

export interface HealthUpdate {
  type: 'full_state' | 'update';
  data: {
    services: ServiceHealthUpdate[];
    changes?: ServiceHealthUpdate[];
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    topology?: any;
    timestamp: string;
  };
}

export interface ServiceHealthUpdate {
  name: string;
  display_name: string;
  category: string;
  status: string;
  response_time_ms: number;
  error?: string;
  url: string;
  critical: boolean;
}

type HealthMessageHandler = (update: HealthUpdate) => void;
type ConnectionStatus = 'connecting' | 'connected' | 'disconnected' | 'error';

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// WEBSOCKET HOOK
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

export function useHealthStream(options?: {
  autoConnect?: boolean;
  reconnectInterval?: number;
  onServiceChange?: (service: ServiceHealthUpdate) => void;
}) {
  const {
    autoConnect = true,
    reconnectInterval = 5000,
    onServiceChange,
  } = options || {};

  const wsRef = useRef<WebSocket | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected');
  const [lastUpdate, setLastUpdate] = useState<HealthUpdate | null>(null);
  const [services, setServices] = useState<ServiceHealthUpdate[]>([]);
  const handlersRef = useRef<Set<HealthMessageHandler>>(new Set());

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;

    setConnectionStatus('connecting');

    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/api/admin-api/health-stream`;

    try {
        const ws = new WebSocket(wsUrl);

        ws.onopen = () => {
            setConnectionStatus('connected');
        };

        ws.onmessage = (event) => {
            try {
                const update = JSON.parse(event.data) as HealthUpdate;
                setLastUpdate(update);
                if (update.type === 'full_state') {
                    setServices(update.data.services || []);
                } else if (update.type === 'update' && update.data.changes) {
                    setServices(prev => {
                        const newServices = [...prev];
                        for (const change of update.data.changes || []) {
                            const idx = newServices.findIndex(s => s.name === change.name);
                            if (idx >= 0) {
                                newServices[idx] = change;
                            } else {
                                newServices.push(change);
                            }
                            if (onServiceChange) {
                                onServiceChange(change);
                            }
                        }
                        return newServices;
                    });
                }
                handlersRef.current.forEach(handler => handler(update));
            } catch (e) {
                // Ignore parse errors
            }
        };

        ws.onclose = () => {
            setConnectionStatus('disconnected');
            if (autoConnect) {
                // eslint-disable-next-line react-hooks/exhaustive-deps
                setTimeout(() => connect(), reconnectInterval);
            }
        };

        ws.onerror = () => {
            setConnectionStatus('error');
        };

        wsRef.current = ws;
    } catch (e) {
        setConnectionStatus('error');
    }
  }, [autoConnect, reconnectInterval, onServiceChange]);

  const disconnect = useCallback(() => {
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (autoConnect) {
      connect();
    }
    return () => {
      disconnect();
    };
  }, [autoConnect, connect, disconnect]);

  const subscribe = useCallback((handler: HealthMessageHandler) => {
    handlersRef.current.add(handler);
    return () => {
      handlersRef.current.delete(handler);
    };
  }, []);

  return {
    connectionStatus,
    lastUpdate,
    services,
    connect,
    disconnect,
    subscribe
  };
}

import { BaseWebSocketManager, BaseWebSocketManagerOptions } from '@supremeai/shared-services';

export interface WebSocketManagerHandlers {
  onOpen?: (event: Event) => void;
  onClose?: (event: CloseEvent) => void;
  onMessage?: (event: MessageEvent) => void;
  onError?: (event: Event) => void;
}

export interface WebSocketManagerOptions extends BaseWebSocketManagerOptions, WebSocketManagerHandlers {}

export default class WebSocketManager extends BaseWebSocketManager {
  private url: string;
  private handlers: WebSocketManagerHandlers;

  constructor(url: string, options: WebSocketManagerOptions = {}) {
    super(options);
    this.url = url;

    // We pass only handlers to store them
    const { maxReconnectAttempts, reconnectBaseDelayMs, heartbeatIntervalMs, ...handlers } = options;
    this.handlers = handlers;
  }

  protected getUrl(): string {
    return this.url;
  }

  protected onOpen(event: Event): void {
    super.onOpen(event);
    this.handlers.onOpen?.(event);
  }

  protected onClose(event: CloseEvent): void {
    super.onClose(event);
    this.handlers.onClose?.(event);
  }

  protected onMessage(event: MessageEvent): void {
    super.onMessage(event);
    this.handlers.onMessage?.(event);
  }

  protected onError(event: Event): void {
    super.onError(event);
    this.handlers.onError?.(event);
  }
}

/**
 * SuperAI Shared Configuration
 * ==============================
 * Secure environment-based configuration with type safety.
 * 
 * @version 3.0.0 (SuperAI Patch)
 */

type EnvConfig = {
  BACKEND_URL: string;
  WS_URL: string;
  APP_NAME: string;
  ENABLE_ANALYTICS: boolean;
  CACHE_ENABLED: boolean;
  RATE_LIMIT_DISPLAY: boolean;
};

/**
 * Get environment variable with validation and fallback.
 * Throws descriptive error in development if required vars missing.
 */
function getEnvVar(key: string, fallback?: string): string {
  const value = import.meta.env[`VITE_${key}`];
  if (!value && !fallback && import.meta.env.DEV) {
    console.warn(`ΓÜá∩╕Å Missing VITE_${key} in .env file`);
  }
  return value || fallback || '';
}

export const CONFIG: EnvConfig = {
  // Backend API URL - use env var or detect automatically
  BACKEND_URL: getEnvVar(
    'BACKEND_URL',
    typeof window !== 'undefined' 
      ? `${window.location.protocol}//${window.location.hostname}:8000`
      : 'https://api.supremeai.com'
  ),

  // WebSocket URL - derive from backend URL
  WS_URL: getEnvVar(
    'WS_URL',
    CONFIG?.BACKEND_URL?.replace(/^http/, 'ws') || 'wss://api.supremeai.com/ws'
  ),

  // Application identity
  APP_NAME: getEnvVar('APP_NAME', 'SuperAI'),

  // Feature flags
  ENABLE_ANALYTICS: getEnvVar('ENABLE_ANALYTICS', 'false') === 'true',
  CACHE_ENABLED: getEnvVar('CACHE_ENABLED', 'true') === 'true',
  RATE_LIMIT_DISPLAY: getEnvVar('RATE_LIMIT_DISPLAY', 'true') === 'true',
};

// Backward compatibility exports
export const BACKEND_URL = CONFIG.BACKEND_URL;
export const WS_URL = CONFIG.WS_URL;
export const APP_NAME = CONFIG.APP_NAME;

/**
 * Validate configuration on import
 */
if (import.meta.env.DEV) {
  console.log('≡ƒöº SuperAI Config:', {
    backend: CONFIG.BACKEND_URL,
    ws: CONFIG.WS_URL,
    features: {
      analytics: CONFIG.ENABLE_ANALYTICS,
      cache: CONFIG.CACHE_ENABLED,
    }
  });
}

import { create } from 'zustand';
import { getApiBaseUrl } from '../utils/api';
import { getFirebaseAuth } from '../firebase';
import { signInWithEmailAndPassword, signOut } from 'firebase/auth';
import { eventBus, Events } from '../lib/eventBus';
import { authService } from '../services/authService';

const decodeJwt = (token: string): Record<string, unknown> | null => {
  try {
    const base64Url = token.split('.')[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
    const decoded = JSON.parse(jsonPayload);

    // Validate decoded structure
    if (!decoded || typeof decoded !== 'object') {
      throw new Error('Decoded JWT payload is not a valid object');
    }

    return decoded;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (e: any) {
    // ≡ƒ¢í∩╕Å αªàαªíαª┐αªƒαª░ αª½αª┐αªòαºìαª╕: αª╕αª╛αªçαª▓αºçαª¿αºìαªƒ αª½αºçαªçαª▓αª░ αª¼αºìαª▓αª╛αª╕αºìαªƒ αªòαª░αºç αªçαª¿αºìαªƒαª╛αª░αª¿αª╛αª▓ αªíαª╛αºƒαª╛αªùαª¿αª╕αºìαªƒαª┐αªò αªƒαºìαª░αºçαª╕ αªÅαª¿αª½αºïαª░αºìαª╕
    console.warn("ΓÜá∩╕Å [JWT_DECODE_LEAK]: Failed to safely parse admin JWT token.", {
      error_message: e?.message || 'Malformed JWT structure',
      token_length: token.length,
      timestamp: new Date().toISOString(),
      token_preview: token.substring(0, 20) + '...'
    });
    return null;
  }
};

// αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: αª¼αºìαª»αª╛αªòαªÅαª¿αºìαªí provisioning_uri αª¿αª╛ αªªαª┐αª▓αºç αªòαºìαª▓αª╛αª»αª╝αºçαª¿αºìαªƒ-αª╕αª╛αªçαªíαºç otpauth URI αªñαºêαª░αª┐ αªòαª░αºç QR αªªαºçαªûαª╛αª¿αºï αª╣αª»αª╝αÑñ
const buildProvisioningUri = (email: string, secret: string): string =>
  `otpauth://totp/SupremeAI:${encodeURIComponent(email)}?secret=${secret}&issuer=SupremeAI&digits=6&period=30`;

interface AdminState {
  adminAuthenticated: boolean;
  adminRole: string | null;
  setAdminRole: (val: string | null) => void;
  adminError: string;
  setAdminError: (val: string) => void;
  handleAdminLogin: (password?: string) => Promise<void>;
  handleAdminLogout: () => void;
  actionStatus: string;
  setActionStatus: (val: string) => void;
  adminSubTab: string;
  setAdminSubTab: (tab: string) => void;
  adminEmail: string;
  setAdminEmail: (val: string) => void;
  otpRequired: boolean;
  setOtpRequired: (val: boolean) => void;
  adminOtp: string;
  setAdminOtp: (val: string) => void;
  totpSetupRequired: boolean;
  setTotpSetupRequired: (val: boolean) => void;
  totpSecret: string;
  setTotpSecret: (val: string) => void;
  provisioningUri: string;
  setProvisioningUri: (val: string) => void;
  resetTotpSetup: () => Promise<void>;
}

export const useAdminStore = create<AdminState>((set, get) => ({
  adminAuthenticated: false,
  adminRole: null,
  setAdminRole: (val) => set({ adminRole: val }),
  adminError: '',
  setAdminError: (val) => set({ adminError: val }),
  actionStatus: '',
  setActionStatus: (val) => set({ actionStatus: val }),
  adminSubTab: 'dashboard',
  setAdminSubTab: (tab) => set({ adminSubTab: tab }),
  adminEmail: '',
  setAdminEmail: (val) => set({ adminEmail: val }),
  otpRequired: false,
  setOtpRequired: (val) => set({ otpRequired: val }),
  adminOtp: '',
  setAdminOtp: (val) => set({ adminOtp: val }),
  totpSetupRequired: false,
  setTotpSetupRequired: (val) => set({ totpSetupRequired: val }),
  totpSecret: '',
  setTotpSecret: (val) => set({ totpSecret: val }),
  provisioningUri: '',
  setProvisioningUri: (val) => set({ provisioningUri: val }),
  handleAdminLogin: async (password?: string) => {
    const { adminEmail, otpRequired, adminOtp, totpSetupRequired } = get();
    const cleanEmail = adminEmail.trim();
    const cleanPassword = password?.trim() || '';

    if (!otpRequired && (!cleanEmail || !cleanPassword)) return;
    set({ adminError: '' });

    try {
      const API_BASE = getApiBaseUrl();

      // αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: getFirebaseAuth() αª¼αºìαª»αª¼αª╣αª╛αª░ αªòαª░αª╛ αª╣αªÜαºìαª¢αºç αª»αª╛αªñαºç Firebase app αªçαª¿αª┐αª╢αª┐αª»αª╝αª╛αª▓αª╛αªçαª£αºçαª╢αª¿ (initializeApp) αª╕αªáαª┐αªòαª¡αª╛αª¼αºç αª╕αª«αºìαª¬αª¿αºìαª¿ αª╣αª»αª╝
      const auth = await getFirebaseAuth();

      let idToken = '';

      if (!otpRequired) {
        // Step 1: Firebase Email/Password Authentication
        try {
          const userCredential = await signInWithEmailAndPassword(auth, cleanEmail, cleanPassword);
          idToken = await userCredential.user.getIdToken(true);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (authErr: any) {
          console.error("Firebase Auth Error:", authErr);
          const firebaseErrMsg = typeof authErr?.message === 'string' 
            ? authErr.message 
            : (authErr?.code ? `Auth error: ${authErr.code}` : (authErr && typeof authErr === 'object' ? JSON.stringify(authErr) : 'Invalid email or password.'));
          set({ adminError: String(firebaseErrMsg) });
          return;
        }

        // Step 2: Send Firebase Token to Backend for Role/TOTP check
        const data = await authService.firebaseLogin(idToken);

        if (data.status === 'otp_required') {
          set({ otpRequired: true });
        } else if (data.status === 'totp_setup_required') {
          // Initiate TOTP Setup
          try {
            const setupData = await authService.firebaseTotpSetup(idToken);
            set({
              totpSetupRequired: true,
              otpRequired: true,
              totpSecret: setupData.secret,
              provisioningUri: setupData.provisioning_uri || buildProvisioningUri(cleanEmail, setupData.secret || '')
            });
          } catch (setupErr: any) {
            const errStr = typeof setupErr.message === 'string' ? setupErr.message : 'Failed to setup TOTP.';
            set({ adminError: errStr });
          }
        } else if (data.token) {
            // Already logged in without OTP (if that logic exists)
        } else {
          set({ adminError: 'Not authorized as admin.' });
        }
      } else {
        // Step 3: Verify TOTP
        // We need the ID token again. Since the user just logged in, they are in auth.currentUser
        const user = auth.currentUser;
        if (!user) {
          set({ adminError: 'Session expired. Please login again.' });
          set({ otpRequired: false });
          return;
        }
        idToken = await user.getIdToken();

        try {
          const data = await authService.firebaseTotpVerify(idToken, adminOtp.trim());
          if (data.token) {
            localStorage.setItem('supreme_admin_jwt', data.token);
            localStorage.setItem('adminToken', data.token);
            const decoded = decodeJwt(data.token);
            if (decoded && typeof decoded.role === 'string') {
              set({ adminRole: decoded.role });
            }
          }
          
          eventBus.emit(Events.AUTH_LOGIN, {
            source: 'admin_store',
            timestamp: Date.now()
          });
          
          set({ adminAuthenticated: true, otpRequired: false, totpSetupRequired: false, adminOtp: '' });
        } catch (verifyErr: any) {
          const errStr = typeof verifyErr.message === 'string' ? verifyErr.message : 'Invalid verification code.';
          set({ adminError: errStr });
        }
      }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      const msg = err && typeof err === 'object' && err.message ? String(err.message) : (typeof err === 'object' ? JSON.stringify(err) : String(err));
      set({ adminError: 'Connection failed: ' + msg });
    }
  },
  handleAdminLogout: async () => {
    try {
      const auth = await getFirebaseAuth();
      // ≡ƒöÑ αª½αª┐αªòαºìαª╕: αª╕αªáαª┐αªò αªƒαºïαªòαºçαª¿ keyαªùαºüαª▓αºï αª¬αª░αª┐αª╖αºìαªòαª╛αª░ αªòαª░αª╛ αª╣αªÜαºìαª¢αºç (αªåαªùαºç αª╢αºüαªºαºü 'adminToken' remove αª╣αªñαºï,
      // αªàαªÑαªÜ adminTokenStore 'supreme_admin_jwt' αª¬αªíαª╝αºç ΓÇö αª½αª▓αºç αª╕αºìαªƒαºçαª▓ αªƒαºïαªòαºçαª¿ αª£αª«αºç αªÑαª╛αªòαªñ)
      const TOKEN_KEYS = ['adminToken', 'supreme_admin_jwt', 'supremeai_auth_token'];
      TOKEN_KEYS.forEach((key) => localStorage.removeItem(key));

      // αª¼αª╛αªéαª▓αª╛ αª«αª¿αºìαªñαª¼αºìαª»: backend-αªÅ αªòαºïαª¿αºï /api/admin/logout endpoint αª¿αª╛αªç (αª¿αª┐αª╢αºìαªÜαª┐αªñ αª╣αª»αª╝αºç αªªαºçαªûαª╛ αªùαºçαª¢αºç)αÑñ
      // αªñαª╛αªç αª╕αºüαªçαªÜ αª¼αºìαª»αª╛αªòαªÅαª¿αºìαªí αªàαª▓ αª¼αºçαª╕αºìαªƒ-αªÅαª½αºïαª░αºìαªƒ call αªÅαªíαª╝αª┐αª»αª╝αºç αª╕αª░αª╛αª╕αª░αª┐ Firebase client signOut αªòαª░αª╛ αª╣αª▓αºïαÑñ
      // JWT αª╕αºìαªƒαºìαª»αª╛αªƒαºçαª▓αºçαª╕ ΓÇö client-side token αª«αºüαª¢αºç αª½αºçαª▓αª╛αªç αª»αªÑαºçαª╖αºìαªƒαÑñ
      await signOut(auth);
      
      eventBus.emit(Events.AUTH_LOGOUT, {
        source: 'admin_store',
        timestamp: Date.now()
      });
    } catch(e) {
      console.error('Logout failed:', e);
    }
    set({ adminAuthenticated: false, adminRole: null, otpRequired: false, adminOtp: '', adminError: '', totpSetupRequired: false, totpSecret: '', provisioningUri: '' });
  },
  resetTotpSetup: async () => {
    set({ adminError: '' });
    try {
      const auth = await getFirebaseAuth();
      const user = auth.currentUser;
      if (!user) {
        set({ adminError: 'Session expired. Please login again.' });
        return;
      }
      const idToken = await user.getIdToken(true);
      const email = (user.email || '').trim() || get().adminEmail.trim();
      const API_BASE = getApiBaseUrl();
      const data = await authService.firebaseTotpSetup(idToken);
      set({
        totpSetupRequired: true,
        otpRequired: true,
        totpSecret: data.secret,
        provisioningUri: data.provisioning_uri || buildProvisioningUri(email, data.secret || ''),
      });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      const msg = err && typeof err === 'object' && err.message ? String(err.message) : (typeof err === 'object' ? JSON.stringify(err) : String(err));
      set({ adminError: 'Connection failed: ' + msg });
    }
  },
}));

import { create } from "zustand";
import { UnifiedChatMessage, ChatConversation } from '../types/chat';
import { eventBus, Events } from '../lib/eventBus';
import { apiClient } from '../services/apiClient';

const MAX_MESSAGES = 1000;

interface ChatState {
  conversations: ChatConversation[];
  activeConversationId: string | null;
  messages: UnifiedChatMessage[];
  input: string;
  isLoading: boolean;
  isStreaming: boolean;
  error: string | null;
  setInput: (text: string) => void;
  addMessage: (msg: Omit<UnifiedChatMessage, "id" | "timestamp">) => void;
  clearMessages: () => void;
  loadConversations: () => Promise<void>;
  saveMessage: (message: UnifiedChatMessage) => Promise<void>;
}

export const useChatStore = create<ChatState>((set, get) => ({
  conversations: [],
  activeConversationId: null,
  messages: [],
  input: "",
  isLoading: false,
  isStreaming: false,
  error: null,
  setInput: (text) => set({ input: text }),

  loadConversations: async () => {
    set({ isLoading: true, error: null });
    try {
      const response = await apiClient.get<ChatConversation[]>('/api/memory/conversations');
      set({
        conversations: response.data || [],
        isLoading: false,
      });
      eventBus.emit(Events.METRICS_UPDATE_AVAILABLE, {
        source: 'chat_store_load',
        count: response.data?.length || 0,
        timestamp: Date.now(),
      });
    } catch (e) {
      console.warn('[ChatStore] Could not load history from backend, using local only');
      set({ isLoading: false, error: null });
    }
  },

  saveMessage: async (message: UnifiedChatMessage) => {
    const state = get();
    if (!['user', 'assistant'].includes(message.role)) return;
    try {
      await apiClient.post('/api/memory/conversations/messages', {
        conversation_id: state.activeConversationId,
        message: {
          id: message.id,
          role: message.role,
          content: message.content,
          timestamp: message.timestamp,
          metadata: message.metadata,
        }
      });
    } catch (e) {
      console.warn('[ChatStore] Failed to persist message to backend:', e);
    }
  },

  addMessage: (msg) => {
    const newMsg: UnifiedChatMessage = {
      ...msg,
      id: crypto.randomUUID ? crypto.randomUUID() : `msg_${Date.now()}_${Math.random()}`,
      timestamp: Date.now(),
    };

    set((s) => {
      // Emit events for passive listeners (dashboards, metrics, etc)
      if (newMsg.role === 'user') {
        eventBus.emit(Events.CHAT_MESSAGE_SENT, newMsg);
      } else if (newMsg.role === 'assistant') {
        eventBus.emit(Events.CHAT_MESSAGE_RECEIVED, newMsg);
      }

      const msgs = [...s.messages, newMsg];
      return {
        messages: msgs.length > MAX_MESSAGES ? msgs.slice(-MAX_MESSAGES) : msgs,
      };
    });

    get().saveMessage(newMsg);
  },
  clearMessages: () => set({ messages: [] }),
}));

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { apiClient } from '../services/apiClient';
import { eventBus, Events } from '../lib/eventBus';

interface ThemeState {
  theme: 'dark' | 'light' | 'system';
  isSyncing: boolean;
  lastSyncedAt: number | null;
  toggleTheme: () => Promise<void>;
  setTheme: (theme: 'dark' | 'light' | 'system') => Promise<void>;
  initializeFromBackend: () => Promise<void>;
  syncToBackend: (theme: 'dark' | 'light' | 'system') => Promise<void>;
}

export const useThemeStore = create<ThemeState>()(
  persist(
    (set, get) => ({
      theme: 'dark',
      isSyncing: false,
      lastSyncedAt: null,
      
      toggleTheme: async () => {
        const newTheme = get().theme === 'dark' ? 'light' : 'dark';
        await get().setTheme(newTheme);
      },
      
      setTheme: async (newTheme) => {
        set({ theme: newTheme });
        
        try {
          set({ isSyncing: true });
          await get().syncToBackend(newTheme);
          set({ isSyncing: false, lastSyncedAt: Date.now() });
        } catch (e) {
          console.warn('Theme sync failed, applied locally only:', e);
          set({ isSyncing: false });
        }
        
        eventBus.emit(Events.THEME_CHANGED, {
          theme: newTheme,
          isDark: newTheme === 'dark',
          timestamp: Date.now(),
          source: 'theme_store',
        });
        
        if (newTheme === 'dark') {
          eventBus.emit(Events.THEME_DARK_MODE, { timestamp: Date.now() });
        } else {
          eventBus.emit(Events.THEME_LIGHT_MODE, { timestamp: Date.now() });
        }
      },
      
      initializeFromBackend: async () => {
        try {
          const response = await apiClient.get('/api/user/preferences');
          const prefs = response.data;
          
          if (prefs?.theme && ['light', 'dark', 'system'].includes(prefs.theme)) {
            set({ 
              theme: prefs.theme,
              lastSyncedAt: Date.now()
            });
            console.log(`[ThemeStore] Loaded theme from backend: ${prefs.theme}`);
          }
        } catch (e) {
          console.warn('[ThemeStore] Failed to load from backend, using local:', e);
        }
      },
      
      syncToBackend: async (theme) => {
        await apiClient.put('/api/user/preferences', { 
          theme,
          updatedAt: new Date().toISOString()
        });
      },
    }),
    {
      name: 'supremeai-theme-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

